use std::fs

fn main() {
    let n_max: int = 200000
    let mut sieve: Vec<bool> = []
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut i: int = 0
    while i <= n_max {
        sieve.push(true)
        i += 1
    }
    let mut p: int = 2
    while p * p <= n_max {
        if sieve[p as usize] {
            let mut m = p * p
            while m <= n_max {
                sieve[m as usize] = false
                m += p
            }
        }
        p += 1
    }
    let mut c: int = 0
    let mut last: int = 0
    i = 0
    while i <= n_max {
        if i >= 2 && sieve[i as usize] {
            c += 1
            last = i
        }
        counts.push(c)
        largest.push(last)
        i += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if largest[n as usize] == 0 {
            println("0 none")
        } else {
            println("${counts[n as usize]} ${largest[n as usize]}")
        }
    }
}

